const fs = require('fs');
const path = require('path');
const brainDir = 'C:\\Users\\mario\\.gemini\\antigravity\\brain';

function searchTranscripts(dir) {
  const files = fs.readdirSync(dir);
  for (const f of files) {
    const full = path.join(dir, f);
    const stat = fs.statSync(full);
    if (stat.isDirectory()) searchTranscripts(full);
    else if (f === 'transcript_full.jsonl') {
      console.log('Checking transcript:', full);
      const lines = fs.readFileSync(full, 'utf8').split('\n');
      for (const line of lines) {
        if (line.includes('subscreen-security') && line.includes('subscreen-family') && line.includes('subscreen-feedback')) {
          console.log('>>> MATCH IN:', full, 'Line length:', line.length);
          fs.writeFileSync('scratch/matched_line.json', line, 'utf8');
        }
      }
    }
  }
}
searchTranscripts(brainDir);
"
